/**
 * Generate packages/sdk/src/abi.ts from the compiled contract.
 *
 * The ABI used to be copied by hand into three places, and the copies drifted:
 * the SDK still had the Decision event without its `preimage` field after the
 * contract gained one. A generated file cannot drift, and `--check` fails CI
 * if someone changes the contract and forgets to regenerate.
 *
 *   node scripts/gen-abi.mjs           write the file
 *   node scripts/gen-abi.mjs --check   exit 1 if the file is stale
 */

import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const target = resolve(root, "packages/sdk/src/abi.ts");

const abi = execFileSync(
  "forge",
  ["inspect", "ZowallGate", "abi", "--json", "--root", resolve(root, "packages/contracts")],
  { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
);

const body = JSON.stringify(JSON.parse(abi), null, 2);
const next = `/**
 * GENERATED by scripts/gen-abi.mjs from the compiled ZowallGate. Do not edit.
 * Regenerate with \`node scripts/gen-abi.mjs\` after changing the contract.
 */

export const GATE_ABI = ${body} as const;
`;

if (process.argv.includes("--check")) {
  const current = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (current !== next) {
    console.error("packages/sdk/src/abi.ts is stale. Run: node scripts/gen-abi.mjs");
    process.exit(1);
  }
  console.log("abi.ts is up to date");
} else {
  writeFileSync(target, next);
  console.log(`wrote ${target}`);
}
